"""Failure recorders for channel-message processing and event composition.

These stages keep no long-lived recorder: a failure is recorded point-in-time
as one failure-counter increment and, when tracing is enabled, one immediately
ended ERROR span backdated to when the failing operation began.
"""

from __future__ import annotations

from typing import Any, Mapping, Optional

from rasa.tracing.voice.metrics import (
    VoiceComponent,
    VoiceOperation,
    record_operation_failure_metric,
)
from rasa.tracing.voice.shared import semconv
from rasa.tracing.voice.spans import set_span_error, start_voice_span


def record_channel_message_failure(
    error: BaseException, *, start_time_ns: Optional[int] = None
) -> None:
    """Record a channel-processing failure.

    Emits an operation-failure metric and, when tracing is enabled, an ERROR span.

    Args:
        error: The exception that failed the message processing.
        start_time_ns: Epoch nanoseconds when the failing operation began
            (``time.time_ns()``); omit to start the span at the current time.
    """
    record_operation_failure_metric(
        component=VoiceComponent.CHANNEL,
        operation=VoiceOperation.PROCESS_CHANNEL_MESSAGE,
        error=error,
    )
    _record_failure_span(
        semconv.SPAN_NAME_PROCESS_CHANNEL_MESSAGE, error, start_time_ns=start_time_ns
    )


def record_event_composition_failure(
    error: BaseException,
    *,
    event_type: Optional[str] = None,
    start_time_ns: Optional[int] = None,
) -> None:
    """Record an event-composition failure.

    Emits an operation-failure metric and, when tracing is enabled, an ERROR span.

    Args:
        error: The exception raised while dispatching the event to handlers.
        event_type: Class name of the failing raw event (never its content).
        start_time_ns: Epoch nanoseconds when the failing dispatch began
            (``time.time_ns()``); omit to start the span at the current time.
    """
    record_operation_failure_metric(
        component=VoiceComponent.COMPOSER,
        operation=VoiceOperation.COMPOSE_EVENT,
        error=error,
    )
    attributes = {semconv.VOICE_TURN_EVENT_TYPE: event_type} if event_type else None
    _record_failure_span(
        semconv.SPAN_NAME_COMPOSE_EVENT,
        error,
        start_time_ns=start_time_ns,
        attributes=attributes,
    )


def _record_failure_span(
    name: str,
    error: BaseException,
    *,
    start_time_ns: Optional[int] = None,
    attributes: Optional[Mapping[str, Any]] = None,
) -> None:
    """Create and immediately end an ERROR span for a failed operation.

    Uses ``start_time_ns`` when provided so the span covers the failed
    operation rather than only its exception handler. A no-op when tracing
    is disabled: the builder hands out a non-recording span.
    """
    span = start_voice_span(name, attributes=attributes, start_time_ns=start_time_ns)
    if not span.is_recording():
        return
    set_span_error(span, error)
    span.end()
